import requests
from bs4 import BeautifulSoup
import urllib3

urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

def web_recon(host, port=80, use_ssl=False, timeout=5, ignore_ssl=False):
    scheme = 'https' if use_ssl else 'http'
    url = f"{scheme}://{host}:{port}"
    try:
        verify = not ignore_ssl
        resp = requests.get(url, timeout=timeout, verify=verify, allow_redirects=True)
        resp.raise_for_status()
        soup = BeautifulSoup(resp.text, 'html.parser')
        title = soup.title.string.strip() if soup.title else 'No title'
        headers = dict(resp.headers)
        technologies = []
        if 'wp-content' in resp.text: technologies.append('WordPress')
        if 'jquery' in resp.text.lower(): technologies.append('jQuery')
        return {
            'status_code': resp.status_code,
            'title': title,
            'server': headers.get('Server', 'Unknown'),
            'content_type': headers.get('Content-Type', ''),
            'headers': headers,
            'technologies': technologies
        }
    except Exception as e:
        return {'error': str(e)}

if __name__ == '__main__':
    info = web_recon('example.com', 80)
    print(info)
